import ast,json,pathlib
base=pathlib.Path('v2/experiments/action_executor/r23')
names=('model.py','test_model.py','checks.py')
allowed={'json','re','copy','unittest','model','hashlib','pathlib'}
imports=[]
for name in names:
    tree=ast.parse((base/name).read_text());compile(tree,str(base/name),'exec')
